draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.moveTo(0, H / 2 + i * 20 + Math.sin(t + i) * 10);
    for (let x = 0; x < W; x++) {
      ctx.lineTo(x, H / 2 + i * 20 + Math.sin(t + x / 50 + i) * 10);
    }
    ctx.stroke();
  }
  ctx.restore();
}
